-- AT-201 part 2b (provisional number): the app_config store. Spec:
-- docs/FAVO_PRD_v7.md §10.4 — "One app_config table, keyed (tenant_id, key),
-- values typed as jsonb, every write audited with before/after and a reason,
-- Admin-only." The first key read is webpos_device_id (§9.10.1, §6.8.2): set at
-- gate zero, read once per tender by beginTender (REQ-065).
-- Generated by drizzle-kit from db/schema.ts. No rows are seeded: until an
-- Admin sets webpos_device_id, beginTender answers TERMINAL_UNREACHABLE and
-- writes no payments row.
-- The reverse is drizzle/down/0037_at201_app_config.down.sql.

CREATE TABLE "app_config" (
	"tenant_id" text DEFAULT 'hofmi' NOT NULL,
	"key" text NOT NULL,
	"value" jsonb NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "app_config_pkey" PRIMARY KEY("tenant_id","key")
);
